@import "https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;600;700&display=swap";

$arche_map_relief: "$arche_map_relief" !default;

:root {
  --erebyx-violet: var(--brand_violet, #7503e0);
  --erebyx-blue: var(--brand_blue, #4492fc);
  --erebyx-violet-light: var(--brand_violet_light, #c4b5fd);
  --erebyx-gold: var(--brand_gold, #fab232);

  --erebyx-gradient: linear-gradient(
    135deg,
    var(--erebyx-violet),
    var(--erebyx-blue)
  );
  --erebyx-gradient-soft: linear-gradient(
    135deg,
    rgba(123, 47, 190, 0.15),
    rgba(77, 139, 245, 0.1)
  );

  --erebyx-font-display:
    "Fireside", "Outfit", "Zen Dots", system-ui, sans-serif;
  --erebyx-font-body:
    "Outfit", "Pathway Gothic One", "Inter", system-ui, sans-serif;
  --erebyx-font-mono:
    "JetBrains Mono", "Fira Code", "Space Grotesk", ui-monospace, monospace;

  --erebyx-glow: var(--constellation_glow_strength, 12);
}

body,
.d-header,
.topic-list,
.topic-body,
.cooked,
button,
input,
select,
textarea {
  font-family: var(--erebyx-font-body);
  font-feature-settings: "ss01" on;
}

h1,
h2,
.display,
.topic-title,
.category-title-link {
  font-family: var(--erebyx-font-display);
  letter-spacing: -0.01em;
  font-weight: 400;
}

h3,
h4,
h5,
h6 {
  font-family: var(--erebyx-font-body);
  font-weight: 600;
  letter-spacing: -0.005em;
}

.discourse-tags,
time,
.relative-date,
.post-date,
.badge-category__name,
.topic-statuses,
.user-card__metadata,
.username,
.post-info,
nav.post-controls .reply-new,
.topic-meta-data,
.crawler-post-meta,
code,
pre,
.monospace,
.text-mono {
  font-family: var(--erebyx-font-mono);
  font-size: 0.875em;
  letter-spacing: 0.02em;
}

.btn-primary,
.btn-cta {
  background: var(--erebyx-gradient);
  border: none;
  color: #ffffff;
  font-family: var(--erebyx-font-body);
  letter-spacing: 0.01em;
  transition:
    filter 0.3s ease,
    box-shadow 0.3s ease;

  &:hover,
  &:focus-visible {
    filter: brightness(1.1);
    box-shadow: 0 0 calc(var(--erebyx-glow) * 1px) rgba(123, 47, 190, 0.45);
  }

  &:focus-visible {
    outline: 2px solid var(--erebyx-violet-light);
    outline-offset: 2px;
  }
}

