.erebyx-hero {
  position: relative;
  width: 100%;

  height: clamp(240px, 38vh, 420px);
  margin: 0 0 2.5rem;
  overflow: hidden;
  background:
    radial-gradient(
      ellipse at 50% 40%,
      rgba(123, 47, 190, 0.18),
      rgba(77, 139, 245, 0.06) 45%,
      transparent 75%
    ),
    linear-gradient(180deg, #0a0a14 0%, #050509 100%);
  border-bottom: 1px solid rgba(123, 47, 190, 0.12);
  isolation: isolate;
  contain: layout paint;
}

.erebyx-hero__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none;
  z-index: 0;

  transform: translateZ(0);
}

.erebyx-hero__static {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(
      1px 1px at 20% 30%,
      rgba(196, 181, 253, 0.6),
      transparent 50%
    ),
    radial-gradient(
      1px 1px at 70% 25%,
      rgba(196, 181, 253, 0.5),
      transparent 50%
    ),
    radial-gradient(
      1.5px 1.5px at 50% 70%,
      rgba(123, 47, 190, 0.7),
      transparent 50%
    ),
    radial-gradient(
      1px 1px at 85% 60%,
      rgba(77, 139, 245, 0.5),
      transparent 50%
    ),
    radial-gradient(
      1px 1px at 15% 80%,
      rgba(196, 181, 253, 0.4),
      transparent 50%
    );
}

.erebyx-hero__content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  text-align: center;
  padding: 2rem 1.5rem;
  pointer-events: none;
}

.erebyx-hero__sigil {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  line-height: 1;
  background: linear-gradient(
    135deg,
    var(--erebyx-violet, #7b2fbe),
    var(--erebyx-blue, #4d8bf5)
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(
    0 0 calc(var(--erebyx-glow, 12) * 1px) rgba(196, 181, 253, 0.4)
  );
}

.erebyx-hero__title {
  font-family: var(--erebyx-font-display, "Zen Dots", system-ui, sans-serif);
  font-size: clamp(2.25rem, 5.5vw, 4rem);
  font-weight: 400;
  letter-spacing: 0.02em;
  margin: 0;
  background: linear-gradient(
    135deg,
    #ffffff 0%,
    var(--erebyx-violet-light, #c4b5fd) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  line-height: 1.05;
}

.erebyx-hero__tag {
  font-family: var(
    --erebyx-font-mono,
    "Space Grotesk",
    ui-monospace,
    monospace
  );
  font-size: clamp(0.7rem, 1.6vw, 0.875rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(241, 245, 249, 0.6);
  margin: 0;
  max-width: 90%;
}

.erebyx-hero__sep {
  color: rgba(123, 47, 190, 0.5);
  margin: 0 0.5em;
}

.erebyx-hero__beta {
  color: var(--erebyx-violet-light, #c4b5fd);
}

.erebyx-hero__fade {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 56px;
  background: linear-gradient(to bottom, transparent, #050509 90%);
  pointer-events: none;
  z-index: 0;
}

@media (max-width: 767px) {
  .erebyx-hero {
    height: 240px;
    margin-bottom: 1.75rem;
  }
