:root {
  --cat-genesis-lounge: var(--erebyx-gold, #d4a437);
  --cat-erebus-build: var(--erebyx-blue, #4d8bf5);
  --cat-nyx-corner: #ec4899;
  --cat-arche-notes: #a78bfa;
  --cat-start-here: var(--erebyx-violet-light, #c4b5fd);
  --cat-announcements: var(--erebyx-violet, #7b2fbe);
  --cat-feature-req: #60a5fa;
  --cat-bug-reports: #f87171;
  --erebyx-read-width: 46rem;
  --erebyx-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --erebyx-fast: 200ms var(--erebyx-ease);
  --erebyx-slow: 400ms var(--erebyx-ease);
  --glow-soft: 0 0 calc(var(--erebyx-glow) * 1px) rgba(123, 47, 190, 0.18);
  --glow-mid: 0 0 calc(var(--erebyx-glow) * 1.6px) rgba(123, 47, 190, 0.32);
  --glow-strong:
    0 4px 24px rgba(123, 47, 190, 0.45),
    0 0 calc(var(--erebyx-glow) * 2px) rgba(196, 181, 253, 0.25);
  --glow-gold: 0 0 calc(var(--erebyx-glow) * 1.4px) rgba(212, 164, 55, 0.35);
}

.categories-boxes-with-topics,
.category-boxes-with-topics,
.categories-list .category-boxes-with-topics {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr));
  gap: 1.25rem;
  margin: 1.5rem 0 2.5rem;
}
.category-box {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 1.5rem 1.5rem 1.25rem;
  background: linear-gradient(
    180deg,
    rgba(15, 15, 28, 0.78),
    rgba(2, 6, 23, 0.92)
  );
  border: 1px solid rgba(123, 47, 190, 0.18);
  border-radius: 14px;
  overflow: hidden;
  isolation: isolate;
  transition:
    transform var(--erebyx-fast),
    border-color var(--erebyx-fast),
    box-shadow var(--erebyx-slow),
    background var(--erebyx-fast);

  &::before {
    content: "";
    position: absolute;
    inset: 0;
    padding: 1px;
    border-radius: 14px;
    background: linear-gradient(
      135deg,
      rgba(123, 47, 190, 0.55) 0%,
      rgba(77, 139, 245, 0.35) 50%,
      rgba(123, 47, 190, 0.15) 100%
    );
    -webkit-mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: 0.6;
    pointer-events: none;
    transition: opacity var(--erebyx-slow);
    z-index: -1;
  }
  &:hover,
  &:focus-within {
    transform: translateY(-2px);
    border-color: rgba(123, 47, 190, 0.42);
    background: linear-gradient(
      180deg,
      rgba(20, 18, 40, 0.85),
      rgba(8, 6, 28, 0.95)
    );
    box-shadow: var(--glow-strong);
    &::before {
      opacity: 1;
    }
    .category-box-heading .category-logo,
    .category-title-link::first-letter {
      transform: scale(1.08);
    }
  }
}

.category-box .category-box-heading {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  margin-bottom: 0.5rem;
  .category-logo {
    width: 2.25rem;
    height: 2.25rem;
    transition: transform var(--erebyx-fast);
  }
  h3 {
    font-family: var(--erebyx-font-display);
    font-size: 1.15rem;
    line-height: 1.2;
    margin: 0;
    letter-spacing: -0.01em;
  }
  a.category-title-link {
    color: #f1f5f9;
    text-decoration: none;
    display: inline-flex;
    align-items: baseline;
    gap: 0.5rem;
    &::first-letter {
      font-size: 1.6em;
      line-height: 1;
      vertical-align: -0.08em;
      color: var(--erebyx-violet-light);
      filter: drop-shadow(0 0 6px rgba(196, 181, 253, 0.35));
      transition:
        transform var(--erebyx-fast),
        filter var(--erebyx-fast);
    }
  }
}

.category-box.category-genesis-lounge,
.category-box[data-category-slug="genesis-lounge"] {
  border-left: 3px solid var(--cat-genesis-lounge);
  .category-title-link::first-letter {
    color: var(--cat-genesis-lounge);
    filter: drop-shadow(0 0 8px rgba(212, 164, 55, 0.55));
    font-size: 1.85em;
  }
  &:hover {
    box-shadow: var(--glow-gold), var(--glow-strong);
  }
}
.category-box.category-erebus-build-log,
.category-box[data-category-slug="erebuss-build-log"],
.category-box[data-category-slug="erebus-build-log"] {
  border-left: 3px solid var(--cat-erebus-build);
  .category-title-link::first-letter {
    color: var(--cat-erebus-build);
    filter: drop-shadow(0 0 8px rgba(77, 139, 245, 0.5));
  }
}
.category-box.category-nyxs-corner,
.category-box[data-category-slug="nyxs-corner"],
.category-box[data-category-slug="nyx-corner"] {
  border-left: 3px solid var(--cat-nyx-corner);
  .category-title-link::first-letter {
    color: var(--cat-nyx-corner);
    filter: drop-shadow(0 0 8px rgba(236, 72, 153, 0.5));
  }
}
.category-box.category-notes-from-the-arche,
.category-box[data-category-slug="notes-from-the-arche"] {
  border-left: 3px solid var(--cat-arche-notes);
  .category-title-link::first-letter {
    color: var(--cat-arche-notes);
    filter: drop-shadow(0 0 8px rgba(167, 139, 250, 0.5));
  }
}

.category-box.category-start-here {
  border-left: 3px solid var(--cat-start-here);
}
.category-box.category-announcements {
  border-left: 3px solid var(--cat-announcements);
}
.category-box.category-feature-requests {
  border-left: 3px solid var(--cat-feature-req);
}
.category-box.category-bug-reports {
  border-left: 3px solid var(--cat-bug-reports);
}

.category-box .featured-topic {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.5rem 0;
  line-height: 1.35;
  border-top: 1px solid rgba(123, 47, 190, 0.08);
  font-family: var(--erebyx-font-body);
  &:first-of-type {
    border-top: none;
  }
  a.title {
    color: rgba(226, 232, 240, 0.85);
    font-size: 0.95rem;
    text-decoration: none;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    transition: color var(--erebyx-fast);
    &:hover {
      color: #ffffff;
