  margin-top: auto;
  padding-top: 0.75rem;
}

@media (max-width: 640px) {
  .categories-boxes-with-topics,
  .category-boxes-with-topics {
    grid-template-columns: 1fr;
    gap: 0.875rem;
  }
  .category-box {
